#include "Core/Geant4DataLocator.hh"

#include "G4Version.hh"

#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <sstream>

#if defined(_WIN32)
#include <windows.h>
#endif

// Exported by G4global; resolves (and caches in the environment) one dataset directory.
const char* G4FindDataDir(const char* name);

namespace Geant4DataLocator {
namespace {

struct Definition {
    const char* env;
    const char* folder;
    bool required;
};

// Dataset folders of Geant4 11.3 (G4FindDataDir.hh generated by the Geant4 build).
#if G4VERSION_NUMBER >= 1130 && G4VERSION_NUMBER < 1140
const Definition kDatasets[] = {
    {"G4LEDATA", "G4EMLOW8.6.1", true},
    {"G4LEVELGAMMADATA", "PhotonEvaporation6.1", true},
    {"G4RADIOACTIVEDATA", "RadioactiveDecay6.1.2", true},
    {"G4PARTICLEXSDATA", "G4PARTICLEXS4.1", true},
    {"G4ENSDFSTATEDATA", "G4ENSDFSTATE3.0", true},
    {"G4NEUTRONHPDATA", "G4NDL4.7.1", false},
    {"G4PIIDATA", "G4PII1.3", false},
    {"G4REALSURFACEDATA", "RealSurface2.2", false},
    {"G4SAIDXSDATA", "G4SAIDDATA2.0", false},
    {"G4ABLADATA", "G4ABLA3.3", false},
    {"G4INCLDATA", "G4INCL1.2", false},
    {"G4CHANNELINGDATA", "G4CHANNELING1.0", false},
};
#else
#error "Update the Geant4 dataset list in Geant4DataLocator.cc for this Geant4 version"
#endif

// getenv without the MSVC deprecation warning; empty when unset.
std::string Environment(const char* name)
{
#if defined(_WIN32)
    char* value = nullptr;
    std::size_t length = 0;
    if (_dupenv_s(&value, &length, name) != 0 || value == nullptr) return {};
    std::string result(value);
    std::free(value);
    return result;
#else
    const char* value = std::getenv(name);
    return value ? value : "";
#endif
}

std::filesystem::path ExecutableDirectory(const char* argv0)
{
#if defined(_WIN32)
    wchar_t buffer[32768];
    const DWORD length = GetModuleFileNameW(nullptr, buffer, static_cast<DWORD>(std::size(buffer)));
    if (length > 0 && length < std::size(buffer)) return std::filesystem::path(buffer).parent_path();
#endif
    std::error_code error;
    const auto path = std::filesystem::absolute(argv0 ? argv0 : "", error);
    return error ? std::filesystem::path() : path.parent_path();
}

bool AnyDataVariableSet()
{
    if (!Environment("GEANT4_DATA_DIR").empty()) return true;
    for (const auto& dataset : kDatasets) {
        if (!Environment(dataset.env).empty()) return true;
    }
    return false;
}

std::string JsonString(const std::string& text)
{
    std::ostringstream out;
    out << '"';
    for (const char c : text) {
        if (c == '"' || c == '\\') out << '\\' << c;
        else if (static_cast<unsigned char>(c) < 0x20) out << ' ';
        else out << c;
    }
    out << '"';
    return out.str();
}

}  // namespace

std::string ApplyGeant4DataFile(const char* argv0)
{
    if (AnyDataVariableSet()) return {};
    const auto file = ExecutableDirectory(argv0) / "geant4-data.txt";
    std::ifstream input(file);
    if (!input) return {};
    std::string line;
    while (std::getline(input, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        const auto first = line.find_first_not_of(" \t");
        if (first == std::string::npos || line[first] == '#') continue;
        const std::string directory = line.substr(first, line.find_last_not_of(" \t") - first + 1);
        std::error_code error;
        const auto path = std::filesystem::u8path(directory);
        if (!std::filesystem::is_directory(path, error)) {
            return "geant4-data.txt names a missing directory: " + directory;
        }
#if defined(_WIN32)
        _putenv_s("GEANT4_DATA_DIR", path.string().c_str());
#else
        setenv("GEANT4_DATA_DIR", path.string().c_str(), 1);
#endif
        return "GEANT4_DATA_DIR set from " + file.u8string();
    }
    return {};
}

std::vector<DatasetStatus> CheckDatasets()
{
    std::vector<DatasetStatus> result;
    for (const auto& dataset : kDatasets) {
        DatasetStatus status;
        status.env = dataset.env;
        status.folder = dataset.folder;
        status.required = dataset.required;
        if (const char* path = G4FindDataDir(dataset.env)) {
            std::error_code error;
            if (std::filesystem::is_directory(std::filesystem::u8path(path), error)) status.path = path;
        }
        result.push_back(status);
    }
    return result;
}

bool WriteReport(std::ostream& out, const std::string& note)
{
    const auto datasets = CheckDatasets();
    bool ok = true;
    out << "{\n  \"schema\": \"g4usim_geant4_data_v1\",\n  \"geant4_version\": " << JsonString(G4Version) << ",\n";
    const std::string base = Environment("GEANT4_DATA_DIR");
    out << "  \"geant4_data_dir\": " << (base.empty() ? "null" : JsonString(base)) << ",\n";
    out << "  \"note\": " << JsonString(note) << ",\n  \"datasets\": [\n";
    for (std::size_t i = 0; i < datasets.size(); ++i) {
        const auto& d = datasets[i];
        if (d.required && d.path.empty()) ok = false;
        out << "    {\"env\": " << JsonString(d.env) << ", \"folder\": " << JsonString(d.folder)
            << ", \"required\": " << (d.required ? "true" : "false") << ", \"found\": "
            << (d.path.empty() ? "false" : "true") << ", \"path\": "
            << (d.path.empty() ? "null" : JsonString(d.path)) << "}" << (i + 1 < datasets.size() ? "," : "") << "\n";
    }
    out << "  ],\n  \"required_complete\": " << (ok ? "true" : "false") << "\n}\n";
    return ok;
}

}  // namespace Geant4DataLocator
